/// <summary>
/// MPJ_3747_AltVendorPayee - KScerri - 13/05/2021
/// The <c>METVendBankAccountsFormEventHandler</c> class containing event handlers
/// </summary>
class METVendBankAccountsFormEventHandler
{
}

Method.Source:
    /// <summary>
    ///  MPJ_3747_AltVendorPayee - KScerri - 13/05/2021
    ///  Fills table respective key.
    /// </summary>
    /// <param name="sender">Form data source</param>
    /// <param name="e">Form event handler</param>
    [
        FormDataSourceEventHandler(formDataSourceStr(VendBankAccounts, METAltVendPaym), FormDataSourceEventType::ValidatingWrite),
        SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface')
    ]
    public static void METAltVendPaym_OnValidatingWrite(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun                 form                = sender.formRun();
        FormDataSource          VendBankAccount_ds  = form.dataSource(formDataSourceStr(VendBankAccounts, VendBankAccount)) as FormDataSource;
        FormDataSource          METAltVendPaym_ds   = form.dataSource(formDataSourceStr(VendBankAccounts, METAltVendPaym)) as FormDataSource;
        VendBankAccount         vendBankAccount     = VendBankAccount_ds.cursor();
        METAltVendPaym          altVendPaym         = METAltVendPaym_ds.cursor();

        if (!vendBankAccount)
        {
            VendBankAccount_ds.write();
        }

        if (altVendPaym.AccountID != vendBankAccount.AccountID)
        {
            altVendPaym.AccountID   = vendBankAccount.AccountID;
        }
    }
